fun <T> Flow<T>.debounceWithImmediateFirst(timeoutMillis: Long): Flow<T> = flow {
    var lastEmitTime = 0L
    collect { value ->
        val currentTime = System.currentTimeMillis()
        if (currentTime - lastEmitTime >= timeoutMillis) {
            lastEmitTime = currentTime
            emit(value)
        }
    }
